class NumberedCanvas(canvas.Canvas):
    """Two-pass canvas to dynamically compute and print total page numbers."""
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._saved_page_states = []

    def showPage(self):
        self._saved_page_states.append(dict(self.__dict__))
        self._startPage()

    def save(self):
        num_pages = len(self._saved_page_states)
        for state in self._saved_page_states:
            self.__dict__.update(state)
            self.draw_page_decorations(num_pages)
            super().showPage()
        super().save()

    def draw_page_decorations(self, total_pages):
        self.saveState()
        self.setFont("Helvetica", 7.5)
        self.setFillColor(colors.HexColor("#64748b"))

        # Running Header
        self.drawString(36, 762, "BaseInt: Enterprise SQL & Database Analytics Agent Technical Manual")
        self.drawRightString(576, 762, "http://localhost:3000")
        self.setStrokeColor(colors.HexColor("#cbd5e1"))
        self.setLineWidth(0.5)
        self.line(36, 756, 576, 756)

        # Running Footer
        self.line(36, 36, 576, 36)
        self.drawString(36, 26, "Confidential & Engineering Reference — sayan-kundu000 / BaseInt")
        page_str = f"Page {self._pageNumber} of {total_pages}"
        self.drawRightString(576, 26, page_str)
        self.restoreState()


def generate_markdown_topics():
    """Write out 37 Markdown files, each with exactly 7 paragraphs."""
    readme_lines = [
        "# BaseInt Technical Documentation Index\n",
        "This directory contains 37 in-depth technical documentation topics across 37 comprehensive pages.",
        "Each topic contains exactly 7 medium-sized paragraphs with full architecture references and `http://localhost:3000` portal links.\n",
        "## Table of Contents\n"
    ]

    for topic in TOPICS:
        t_id = topic["id"]
        title = topic["title"]
        paragraphs = topic["paragraphs"]

        md_filename = f"topic_{t_id}.md"
        md_path = TOPICS_DIR / md_filename
        
        md_content = f"# Topic {t_id}: {title}\n\n"
        md_content += "\n\n".join(paragraphs)
        md_content += f"\n\n---\n*BaseInt Reference Portal: [http://localhost:3000/docs/topic-{t_id}](http://localhost:3000/docs/topic-{t_id})*\n"

        md_path.write_text(md_content, encoding="utf-8")
        readme_lines.append(f"- **[Topic {t_id}: {title}](topics/{md_filename})** ([localhost:3000 view](http://localhost:3000/docs/topic-{t_id}))")

    (DOCS_DIR / "README.md").write_text("\n".join(readme_lines), encoding="utf-8")
    print(f"Generated 37 Markdown topic files in {TOPICS_DIR} and docs/README.md.")


def build_pdf_document():
    """Build a precise 37-page PDF document using ReportLab Platypus."""
    doc = SimpleDocTemplate(
        str(PDF_OUTPUT_PATH),
        pagesize=letter,
        leftMargin=36,
        rightMargin=36,
        topMargin=46,
        bottomMargin=46,
    )

    styles = getSampleStyleSheet()

    # Title Style
    title_style = ParagraphStyle(
        name='TopicTitle',
        fontName='Helvetica-Bold',
        fontSize=12.5,
        leading=15,
        textColor=colors.HexColor("#1e3a8a"),
        spaceAfter=4,
    )

    # Subtitle / Topic Number Style
    topic_tag_style = ParagraphStyle(
        name='TopicTag',
        fontName='Helvetica-Bold',
        fontSize=7.5,
        leading=9.5,
        textColor=colors.HexColor("#2563eb"),
        spaceAfter=2,
    )

    # Body Paragraph Style calibrated to fit exactly 7 paragraphs per page
    body_style = ParagraphStyle(
        name='TopicBody',
        fontName='Helvetica',
        fontSize=7.6,
        leading=9.8,
        textColor=colors.HexColor("#1e293b"),
        alignment=4,  # Justified
        spaceAfter=4.5,
    )

    story = []

    for idx, topic in enumerate(TOPICS):
        t_id = topic["id"]
        title = topic["title"]
        paragraphs = topic["paragraphs"]

        # Topic Header Block
        story.append(Paragraph(f"BASEINT TECHNICAL REFERENCE &bull; TOPIC {t_id} OF 37", topic_tag_style))
        story.append(Paragraph(f"Topic {t_id}: {title}", title_style))
        story.append(HRFlowable(width="100%", thickness=0.75, color=colors.HexColor("#3b82f6"), spaceAfter=5, spaceBefore=1))

        # Exactly 7 Paragraphs
        for p_text in paragraphs:
            # Escape XML entities for ReportLab Platypus
            safe_text = p_text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            # Highlight localhost:3000 links in bold blue
            formatted_p = safe_text.replace(
                "http://localhost:3000",
                '<font color="#1d4ed8"><b>http://localhost:3000</b></font>'
            )
            story.append(Paragraph(formatted_p, body_style))

        # Page break after every topic (except after the final 37th topic)
        if idx < len(TOPICS) - 1:
            story.append(PageBreak())

    doc.build(story, canvasmaker=NumberedCanvas)
    
    # Verify exact page count using pypdf
    reader = pypdf.PdfReader(str(PDF_OUTPUT_PATH))
    page_count = len(reader.pages)
    print(f"Compiled PDF: {PDF_OUTPUT_PATH}")
    print(f"Verified Page Count: {page_count} pages (Target: 37 pages).")

    if page_count != 37:
        print(f"WARNING: Page count is {page_count}, expected exactly 37!", file=sys.stderr)
        return False
    return True


if __name__ == "__main__":
    generate_markdown_topics()
    success = build_pdf_document()
    if not success:
        sys.exit(1)
    print("Documentation build completed successfully!")
